gsl.gsl_multifit_covar.restype = ctypes.POINTER(GSLMatrix)

def covariance_matrix(jacobian, epsrel, dim):
    if dim != jacobian.shape[0] or dim != jacobian.shape[1]:
        raise ValueError("Invalid dimensions.")

    gsl_jacobian = numpy_to_gsl_matrix(jacobian)
    gsl_covariance = gsl.gsl_multifit_covar(gsl_jacobian, epsrel)
    covariance = gsl_matrix_to_numpy(gsl_covariance)

    gsl.gsl_matrix_free(gsl_covariance)

    return covariance.tolist()

