import numpy as np

class GSLMatrix:
    def __init__(self, rows, cols):
        self.rows = rows
        self.cols = cols
        self.gsl_matrix = ctypes.c_void_p()
        gsl.gsl_matrix_alloc.argtypes = [ctypes.c_int, ctypes.c_int]
        gsl.gsl_matrix_alloc.restype = ctypes.c_void_p
        self.gsl_matrix = gsl.gsl_matrix_alloc(rows, cols)

    def __del__(self):
        gsl.gsl_matrix_free(self.gsl_matrix)

def numpy_to_gsl_matrix(np_array):
    gsl_matrix = GSLMatrix(np_array.shape[0], np_array.shape[1])
    for i in range(np_array.shape[0]):
        for j in range(np_array.shape[1]):
            gsl.gsl_matrix_set(gsl_matrix.gsl_matrix, i, j, np_array[i, j])
    return gsl_matrix

def gsl_matrix_to_numpy(gsl_matrix):
    np_array = np.zeros((gsl_matrix.rows, gsl_matrix.cols))
    for i in range(gsl_matrix.rows):
        for j in range(gsl_matrix.cols):
            np_array[i, j] = gsl.gsl_matrix_get(gsl_matrix.gsl_matrix, i, j)
    return np_array

def covariance_matrix(jacobian, epsrel, dim):
