class GSLMatrix:
    def __init__(self, matrix):
        self.matrix = matrix
        self.rows, self.cols = np.shape(matrix)

    def matrix_to_gsl(self):
        gsl_matrix = gsl.gsl_matrix_alloc(self.rows, self.cols)
        for i in range(self.rows):
            for j in range(self.cols):
                gsl.gsl_matrix_set(gsl_matrix, i, j, self.matrix[i][j])
        return gsl_matrix

    def gsl_matrix_to_numpy(self, gsl_matrix):
        matrix = np.zeros((self.rows, self.cols))
        for i in range(self.rows):
            for j in range(self.cols):
                matrix[i][j] = gsl.gsl_matrix_get(gsl_matrix, i, j)
        return matrix

def compute_matrix_exponential(matrix, mode):
    gsl_matrix = GSLMatrix(matrix).matrix_to_gsl()
    gsl.gsl_linalg_exponential_ss(gsl_matrix, mode)
    return GSLMatrix(matrix).gsl_matrix_to_numpy(gsl_matrix)

