def cholesky_decomposition(input_matrix):
    # Allocate the required GSL data structures
    matrix = gsl_matrix_alloc(len(input_matrix), len(input_matrix))
    permutation = gsl_permutation_alloc(len(input_matrix))

    # Initialize the matrix
    for i in range(len(input_matrix)):
        for j in range(len(input_matrix)):
            gsl_matrix_set(matrix, i, j, input_matrix[i][j])

    # Perform the LDLT decomposition
    status = gsl_linalg_pcholesky_decomp(matrix, permutation, None)

    # Check for errors
    if status != 0:
        raise Exception("Error during LDLT decomposition")

    # Convert the matrix and permutation to Python lists
    result_matrix = [[gsl_matrix_get(matrix, i, j) for j in range(len(input_matrix))] for i in range(len(input_matrix))]
    permutation_vector = [gsl_permutation_get(permutation, i) for i in range(len(input_matrix))]

    return result_matrix, permutation_vector

