def cholesky_decomp(matrix):
    """Performs Cholesky decomposition."""
    gsl_matrix = GSLMatrix(ctypes.c_int(len(matrix)), ctypes.c_int(len(matrix[0])), matrix)
    status = gsl.gsl_linalg_cholesky_decomp(gsl_matrix)

